update product_sku
set sku_code = case id
        when #{sku.id} then #{sku.skuCode} 
    end,
    name = case id
        when #{sku.id} then #{sku.name} 
    end,
    spec_json = case id
        when #{sku.id} then #{sku.specJson} 
    end,
    price = case id
        when #{sku.id} then #{sku.price} 
    end,
    market_price = case id
        when #{sku.id} then #{sku.marketPrice} 
    end,
    image = case id
        when #{sku.id} then #{sku.image} 
    end
where deleted = 0
and id in
#{sku.id}
